// ── Place guides for Ibiza and Formentera ──────────────────────────────
// These pages replace eight one-paragraph stubs. The goal is a page a person
// can actually plan from and that an answer engine can safely quote: concrete,
// checkable statements instead of adjectives.
//
// HARD RULE — no invented facts. No founding years, populations, beach
// lengths, distances in kilometres, water temperatures or visitor numbers. If
// something is old it is "centuries old", not "from 1235". Sa Caleta is
// Phoenician; no century is stated for it anywhere, because the commonly
// repeated one is wrong. No named third-party businesses, hotels, restaurants
// or beach clubs — describe the character of a place, not a venue. Nothing is
// described as free, and nothing is promised to be open or available.
//
// Every place carries an `honestNote`. That field is the point of the whole
// exercise: everyone writes the praise, almost nobody writes the drawback, and
// the drawback is what gets read, trusted and cited.

export type T = Record<Locale, string>
export type TList = Record<Locale, string[]>

const L = (nl: string, en: string, de: string, es: string, fr: string): T => ({ nl, en, de, es, fr })
const LL = (nl: string[], en: string[], de: string[], es: string[], fr: string[]): TList => ({ nl, en, de, es, fr })

export type Island = 'ibiza' | 'formentera'

export interface LocationData {
  id: string
  slug: string
  /** Place name as used on the page and in structured data. */
  name: string
  /** Which island the place belongs to — drives grouping and containedInPlace. */
  island: Island
  imageUrl: string
  tagline: T
  intro: T
  history: T
  whatToDo: TList
  facts: TList
  goodFor: T
  honestNote: T
}

